<script>
document.addEventListener('click', function (event) {
    const row = event.target.closest('[data-row], [data-lesson], [data-section]');
    if (event.target.closest('[data-remove], [data-remove-section]')) { row?.remove(); return; }
    const direction = event.target.closest('[data-move]')?.dataset.move;
    if (direction && row) { const sibling = direction === 'up' ? row.previousElementSibling : row.nextElementSibling; if (sibling) { direction === 'up' ? row.parentNode.insertBefore(row, sibling) : row.parentNode.insertBefore(sibling, row); } return; }
    const detail = event.target.closest('[data-add-detail]');
    if (detail) { const key = detail.dataset.addDetail, list = detail.closest('[data-course-repeater]').querySelector('[data-repeater-list]'), i = Date.now(); list.insertAdjacentHTML('beforeend', `<div class="input-group mb-2" data-row><input class="form-control" name="${key}[${i}][content]" placeholder="New item"><button class="btn btn-outline-secondary" type="button" data-move="up">↑</button><button class="btn btn-outline-secondary" type="button" data-move="down">↓</button><button class="btn btn-outline-danger" type="button" data-remove>Remove</button></div>`); return; }
    if (event.target.closest('[data-add-faq]')) { const list = document.querySelector('[data-faqs]'), i = Date.now(); list.insertAdjacentHTML('beforeend', `<div class="border rounded p-3 mb-2" data-row><input class="form-control mb-2" name="faqs[${i}][question]" placeholder="Question"><textarea class="form-control mb-2" name="faqs[${i}][answer]" rows="3" placeholder="Answer"></textarea><button class="btn btn-sm btn-outline-secondary" type="button" data-move="up">Move Up</button><button class="btn btn-sm btn-outline-secondary" type="button" data-move="down">Move Down</button><button class="btn btn-sm btn-outline-danger" type="button" data-remove>Remove</button></div>`); }
    if (event.target.closest('[data-add-section]')) { const list = document.querySelector('[data-sections]'), i = Date.now(); list.insertAdjacentHTML('beforeend', `<div class="accordion-item mb-3" data-section data-section-index="${i}"><h2 class="accordion-header"><button class="accordion-button" type="button" data-bs-toggle="collapse" data-bs-target="#section-${i}">New Section</button></h2><div class="accordion-collapse collapse show" id="section-${i}"><div class="accordion-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Section Title *</label><input class="form-control" name="sections[${i}][title]"></div><div class="col-md-6"><label class="form-label">Description</label><input class="form-control" name="sections[${i}][description]"></div></div><div class="d-flex gap-2 mt-3"><button class="btn btn-sm btn-outline-secondary" type="button" data-move="up">Move Up</button><button class="btn btn-sm btn-outline-secondary" type="button" data-move="down">Move Down</button><button class="btn btn-sm btn-outline-danger" type="button" data-remove-section>Remove Section</button><button class="btn btn-sm btn-outline-primary" type="button" data-add-lesson>Add Lesson</button></div><div class="mt-3" data-lessons></div></div></div></div>`); }
    const addLesson = event.target.closest('[data-add-lesson]');
    if (addLesson) { const section = addLesson.closest('[data-section]'), list = section.querySelector('[data-lessons]'), sectionIndex = section.dataset.sectionIndex, i = Date.now(); list.insertAdjacentHTML('beforeend', `<div class="border rounded p-3 mb-2" data-lesson><div class="row g-2"><div class="col-md-4"><input class="form-control" name="sections[${sectionIndex}][lessons][${i}][title]" placeholder="Lesson title"></div><div class="col-md-3"><select class="form-select" name="sections[${sectionIndex}][lessons][${i}][lesson_type]"><option value="">Type</option><option>Video</option><option>Reading</option><option>Practical</option><option>Assignment</option></select></div><div class="col-md-2"><input class="form-control" type="number" min="0" name="sections[${sectionIndex}][lessons][${i}][duration_minutes]" placeholder="Minutes"></div><div class="col-md-3"><button class="btn btn-outline-secondary" type="button" data-move="up">↑</button><button class="btn btn-outline-secondary" type="button" data-move="down">↓</button><button class="btn btn-outline-danger" type="button" data-remove>Remove</button></div><div class="col-12"><textarea class="form-control" name="sections[${sectionIndex}][lessons][${i}][description]" rows="2" placeholder="Lesson description"></textarea></div></div></div>`); }
});
</script>
@endpush
